    fclose(file);

    // Process the buffer (for demonstration, just print the first few samples)
    for (int i = 0; i < 10 && i < read_count; i++) {
        printf("Sample %d: %d\n", i, buffer[i]);
    }

    // Free the allocated memory
    free(buffer);

    return EXIT_SUCCESS;
}
